UPDATE artists SET birth_year = 1953, date_of_birth = '1953-04-06',
       death_year = 2026, date_of_death = '2026-06-22',
       middle_name = 'Manuel', second_last_name = 'Suazo', ended = true,
       occupations = '["bandleader","composer"]'::jsonb, genres = ARRAY['salsa-classic']::text[]
       WHERE slug = 'jose-bello';

